3	/**
4	 * Messages server actions — all mutations go through here.
5	 *
6	 * Each action:
7	 *  - Resolves studioId from authenticated session
8	 *  - Validates input with Zod
9	 *  - Returns { ok, data?, error? }
10	 *  - Calls revalidatePath where appropriate
11	 */
12	
13	import { revalidatePath } from 'next/cache'
14	import { z } from 'zod'
15	import { getAuthenticatedUser } from '@/lib/supabase/server'
16	import { sendSmsToClient, sendEmailToClient } from '@/lib/messaging/send'
17	import {
18	  markConversationRead,
19	  assignConversation,
20	  archiveConversation,
21	  starConversation,
22	  linkConversationToClient,
23	} from '@/lib/messaging/mutations'
24	import { logger } from '@/lib/logger'
25	
26	// ─── Types ────────────────────────────────────────────────────────────────────
27	
28	export interface ActionResult<T = undefined> {
29	  ok: boolean
30	  data?: T | undefined
31	  error?: string | undefined
32	}
33	
34	// ─── sendMessageAction ────────────────────────────────────────────────────────
35	
36	const SendMessageSchema = z.object({
37	  conversationId: z.string().uuid(),
38	  clientId: z.string().uuid(),
39	  body: z.string().min(1).max(1600),
40	  channel: z.enum(['sms', 'email']),
41	  subject: z.string().max(200).optional(),
42	})
43	
44	export async function sendMessageAction(
45	  input: z.infer<typeof SendMessageSchema>,
46	): Promise<ActionResult<{ commId: string }>> {
47	  const authUser = await getAuthenticatedUser()
48	  if (!authUser) return { ok: false, error: 'Unauthorized' }
49	
50	  const parsed = SendMessageSchema.safeParse(input)
51	  if (!parsed.success) {
52	    return { ok: false, error: parsed.error.issues[0]?.message ?? 'Invalid input' }
53	  }
54	
55	  const { conversationId, clientId, body, channel, subject } = parsed.data
56	  const { studioId } = authUser
57	
58	  try {
59	    if (channel === 'sms') {
60	      const result = await sendSmsToClient(
61	        { studioId, clientId, body },
62	        authUser.user.id,
63	      )
64	      if (!result.ok) {
65	        return { ok: false, error: result.error ?? 'Failed to send SMS' }
66	      }
67	      revalidatePath(`/messages/${conversationId}`)
68	      revalidatePath('/messages')
69	      return { ok: true, data: { commId: result.commId ?? '' } }
70	    }
71	
72	    if (channel === 'email') {
73	      const result = await sendEmailToClient(
74	        {
75	          studioId,
76	          clientId,
77	          subject: subject ?? '(no subject)',
78	          body,
79	        },
80	        authUser.user.id,
81	      )
82	      if (!result.ok) {
83	        return { ok: false, error: result.error ?? 'Failed to send email' }
84	      }
85	      revalidatePath(`/messages/${conversationId}`)
86	      revalidatePath('/messages')
87	      return { ok: true, data: { commId: result.commId ?? '' } }
88	    }
89	
90	    return { ok: false, error: 'Unsupported channel' }
91	  } catch (err) {
92	    logger.error({ err, conversationId }, 'sendMessageAction: unexpected error')
93	    return { ok: false, error: 'Failed to send message' }
94	  }
95	}
