// ─── listConversations ────────────────────────────────────────────────────────

export async function listConversations(
  studioId: string,
  filters: ListConversationsFilters = {},
): Promise<ListConversationsResult> {
  const supabase = await createClient()
  const limit = filters.limit ?? 50
  const offset = filters.offset ?? 0

  let query = supabase
    .from('conversations')
    .select(
      `
      *,
      client:clients (
        id, first_name, last_name, email, phone,
        total_spent_cents, total_sessions, no_show_count, tags
      )
    `,
      { count: 'exact' },
    )
    .eq('studio_id', studioId)
    .order('last_message_at', { ascending: false, nullsFirst: false })
    .range(offset, offset + limit - 1)

  // Archived / active filter
  if (filters.archived === true) {
    query = query.not('archived_at', 'is', null)
  } else {
    query = query.is('archived_at', null)
  }

  if (filters.channel) {
    query = query.eq('channel', filters.channel)
  }

  if (filters.unreadOnly) {
    query = query.gt('unread_count', 0)
  }

  if (filters.triageTag) {
    query = query.eq('triage_tag', filters.triageTag)
  }

  if (filters.starred === true) {
    query = query.eq('starred', true)
  }

  if (filters.resolved === true) {
    query = query.not('resolved_at', 'is', null)
  } else if (filters.resolved === false) {
    query = query.is('resolved_at', null)
  }

  // assignedTo filter — 'me' is resolved by caller passing actual userId
  // (server action resolves via auth session before calling listConversations)
  if (filters.assignedTo) {
    query = query.eq('assigned_to', filters.assignedTo)
  } else if (filters.assignedToMe) {
    // legacy compat — prefer assignedTo='me' resolved to userId by action layer
    // no-op here: caller must resolve userId and pass as assignedTo
  }

  if (filters.search) {
    // Search against display_name or external_identifier
    query = query.or(
      `display_name.ilike.%${filters.search}%,external_identifier.ilike.%${filters.search}%`,
    )
  }

  const { data, error, count } = await query

  if (error) {
    logger.error({ err: error, studioId }, 'messaging: listConversations failed')
    return { conversations: [], total: 0 }
  }

  return {
    conversations: (data ?? []) as ConversationWithClient[],
    total: count ?? 0,
  }
}

