// ─── getChannelUnreadCounts ────────────────────────────────────────────────────

export async function getChannelUnreadCounts(
  studioId: string,
): Promise<Record<Channel, number>> {
  const supabase = await createClient()

  // Single query: group by channel for unread (unread_count > 0) active conversations
  const { data, error } = await supabase
    .from('conversations')
    .select('channel, unread_count')
    .eq('studio_id', studioId)
    .is('archived_at', null)
    .gt('unread_count', 0)

  const counts: Record<Channel, number> = {
    sms: 0,
    email: 0,
    instagram: 0,
    whatsapp: 0,
    webchat: 0,
    phone: 0,
  }

  if (error) {
    logger.error({ err: error, studioId }, 'messaging: getChannelUnreadCounts failed')
    return counts
  }

  for (const row of data ?? []) {
    // Map DB channel values to our 7-channel rail
    const ch = row.channel as string
    if (ch === 'sms') counts.sms += row.unread_count
    else if (ch === 'email') counts.email += row.unread_count
    else if (ch === 'instagram') counts.instagram += row.unread_count
    else if (ch === 'facebook') counts.instagram += row.unread_count // FB DMs map to instagram rail slot
    else if (ch === 'voice') counts.phone += row.unread_count
    // webchat + whatsapp are future channels — schema expansion adds them
  }

  return counts
}

// ─── getConversationContext ────────────────────────────────────────────────────

export async function getConversationContext(
  studioId: string,
  conversationId: string,
): Promise<ConversationContext> {
  const supabase = await createClient()

  // First resolve client_id from the conversation
  const { data: conv } = await supabase
    .from('conversations')
    .select('client_id')
    .eq('id', conversationId)
    .eq('studio_id', studioId)
    .single()

  const clientId = conv?.client_id ?? null

  if (!clientId) {
    return {
      client: null,
      upcomingBookings: [],
      recentBookings: [],
      latestPayment: null,
      consentSubmissions: [],
      referenceImages: [],
      internalNotes: [],
      ltv: 0,
    }
  }

  // Parallel fetches — each sub-query fails gracefully
  const [
    clientResult,
    upcomingResult,
    recentResult,
    paymentResult,
    consentResult,
    refImagesResult,
    notesResult,
  ] = await Promise.allSettled([
    // Full client profile
    supabase
      .from('clients')
      .select('id, first_name, last_name, email, phone, avatar_url, total_spent_cents, total_sessions, no_show_count, tags')
      .eq('id', clientId)
      .eq('studio_id', studioId)
      .single(),

    // Upcoming bookings (next 5)
    supabase
      .from('bookings')
      .select('id, scheduled_at, status, price_cents, services(name)')
      .eq('studio_id', studioId)
      .eq('client_id', clientId)
      .gt('scheduled_at', new Date().toISOString())
      .order('scheduled_at', { ascending: true })
      .limit(5),

    // Recent finished bookings (last 5)
    supabase
      .from('bookings')
      .select('id, scheduled_at, status, price_cents, services(name)')
      .eq('studio_id', studioId)
      .eq('client_id', clientId)
      .lte('scheduled_at', new Date().toISOString())
      .order('scheduled_at', { ascending: false })
      .limit(5),

    // Latest payment
    supabase
      .from('bookings')
      .select('id, price_cents, status, created_at, deposit_status')
      .eq('studio_id', studioId)
      .eq('client_id', clientId)
      .order('created_at', { ascending: false })
      .limit(1)
      .single(),

    // Consent submissions
    supabase
      .from('consent_form_submissions')
      .select('id, signed_at, status, consent_form_templates(name)')
      .eq('studio_id', studioId)
      .eq('client_id', clientId)
      .order('created_at', { ascending: false })
      .limit(5),

    // Reference images from comm metadata attachments for this client
    supabase
      .from('client_communications')
      .select('metadata, created_at')
      .eq('studio_id', studioId)
      .eq('client_id', clientId)
      .not('metadata', 'eq', '{}')
      .order('created_at', { ascending: false })
      .limit(40),

    // Internal notes for this conversation
    supabase
      .from('client_communications')
      .select('id, conversation_id, channel, direction, subject, body, status, sent_at, delivered_at, opened_at, error, provider_message_id, metadata, is_internal_note, scheduled_for, reply_to_message_id, created_at, updated_at')
      .eq('studio_id', studioId)
      .eq('conversation_id', conversationId)
      .eq('is_internal_note', true)
      .order('created_at', { ascending: false })
      .limit(3),
  ])

  // Resolve client
  const clientData =
    clientResult.status === 'fulfilled' && !clientResult.value.error
      ? (clientResult.value.data as ClientSummary | null)
      : null

  // Resolve upcoming bookings
  const upcomingBookings: ClientBookingSummary[] =
    upcomingResult.status === 'fulfilled' && !upcomingResult.value.error
      ? (upcomingResult.value.data ?? []).map((b) => ({
          id: b.id,
          scheduled_at: b.scheduled_at,
          status: b.status,
          price_cents: b.price_cents,
          service_name: Array.isArray(b.services)
            ? (b.services[0] as { name: string } | undefined)?.name ?? null
            : (b.services as { name: string } | null)?.name ?? null,
        }))
      : []

  // Resolve recent bookings
  const recentBookings: ClientBookingSummary[] =
    recentResult.status === 'fulfilled' && !recentResult.value.error
      ? (recentResult.value.data ?? []).map((b) => ({
          id: b.id,
          scheduled_at: b.scheduled_at,
          status: b.status,
          price_cents: b.price_cents,
          service_name: Array.isArray(b.services)
            ? (b.services[0] as { name: string } | undefined)?.name ?? null
            : (b.services as { name: string } | null)?.name ?? null,
        }))
      : []

  // Resolve latest payment
  let latestPayment: LatestPaymentSummary | null = null
  if (paymentResult.status === 'fulfilled' && !paymentResult.value.error && paymentResult.value.data) {
    const p = paymentResult.value.data as {
      id: string
      price_cents: number
      status: string
      created_at: string
      deposit_status: string | null
    }
    latestPayment = {
      id: p.id,
      amount_cents: p.price_cents,
      status: p.status,
      created_at: p.created_at,
      deposit_status: p.deposit_status,
    }
  }

  // Resolve consent submissions
  const consentSubmissions: ConsentSubmissionSummary[] =
    consentResult.status === 'fulfilled' && !consentResult.value.error
      ? (consentResult.value.data ?? []).map((s) => {
          const tpl = s.consent_form_templates as { name: string } | null
          return {
            id: s.id,
            template_name: tpl?.name ?? null,
            signed_at: s.signed_at ?? null,
            status: s.status,
          }
        })
      : []

  // Resolve reference images from comm metadata
  const referenceImages: ReferenceImage[] = []
  if (refImagesResult.status === 'fulfilled' && !refImagesResult.value.error) {
    for (const row of refImagesResult.value.data ?? []) {
      const meta = row.metadata as Record<string, unknown> | null
      if (!meta) continue
      const attachments = meta['attachments']
      if (Array.isArray(attachments)) {
        for (const att of attachments) {
          if (typeof att === 'string' && referenceImages.length < 20) {
            referenceImages.push({ url: att, created_at: row.created_at })
          } else if (
            typeof att === 'object' &&
            att !== null &&
            typeof (att as Record<string, unknown>)['url'] === 'string' &&
            referenceImages.length < 20
          ) {
            referenceImages.push({
              url: (att as Record<string, unknown>)['url'] as string,
              created_at: row.created_at,
            })
          }
        }
      }
    }
  }

  // Resolve internal notes
  const internalNotes: ConversationMessage[] =
    notesResult.status === 'fulfilled' && !notesResult.value.error
      ? (notesResult.value.data ?? []) as ConversationMessage[]
      : []

  const ltv = clientData?.total_spent_cents ?? 0

  return {
    client: clientData,
    upcomingBookings,
    recentBookings,
    latestPayment,
    consentSubmissions,
    referenceImages,
    internalNotes,
    ltv,
  }
}

// ─── listMessageTemplates ──────────────────────────────────────────────────────

export async function listMessageTemplates(
  studioId: string,
  opts: { category?: MessageTemplate['category']; channel?: MessageTemplate['channel'] } = {},
): Promise<MessageTemplate[]> {
  const supabase = await createClient()

  let query = supabase
    .from('message_templates')
    .select('*')
    .eq('studio_id', studioId)
    .order('is_default', { ascending: false })
    .order('name', { ascending: true })

  if (opts.category) {
    query = query.eq('category', opts.category)
  }

  if (opts.channel) {
    // 'both' templates apply to any channel
    query = query.or(`channel.eq.${opts.channel},channel.eq.both`)
  }

  const { data, error } = await query

  if (error) {
    logger.error({ err: error, studioId }, 'messaging: listMessageTemplates failed')
    return []
  }

  return (data ?? []) as MessageTemplate[]
}

// ─── listAutoReplyRules ────────────────────────────────────────────────────────

export type AutoReplyRuleWithTemplate = AutoReplyRule & {
  template: MessageTemplate | null
}

export async function listAutoReplyRules(studioId: string): Promise<AutoReplyRuleWithTemplate[]> {
  const supabase = await createClient()

  const { data, error } = await supabase
    .from('auto_reply_rules')
    .select('*, template:message_templates(*)')
    .eq('studio_id', studioId)
    .order('created_at', { ascending: true })

  if (error) {
    logger.error({ err: error, studioId }, 'messaging: listAutoReplyRules failed')
    return []
  }

  return (data ?? []) as AutoReplyRuleWithTemplate[]
}

