/**
 * Messaging triage + smart-reply engine.
 *
 * v1: rule-based, deterministic. AI-ready signature — swap generateSmartReplies
 * implementation for Anthropic call in v2 without changing callers.
 *
 * TODO(v2-ai): replace generateSmartReplies body with streaming Claude call
 * behind feature gate `messaging_ai_replies`.
 */

import { createClient } from '@/lib/supabase/server'
import { createServiceRoleClient } from '@/lib/supabase/server'
import { enqueueJob } from '@/lib/queue'
import { logger } from '@/lib/logger'
import { listAutoReplyRules } from './queries'
import type { TriageTag, ConversationWithClient, ConversationMessage, ClientBookingSummary } from './queries'

// ─── Smart Reply types ─────────────────────────────────────────────────────────

export interface SmartReplyContext {
  conversation: ConversationWithClient
  lastInboundMessage: ConversationMessage | null
  upcomingBookings: ClientBookingSummary[]
}

export type SmartReplyAction =
  | { kind: 'send_template'; templateSlug: string }
  | { kind: 'open_calendar_reschedule'; bookingId: string }
  | { kind: 'share_portfolio' }
  | { kind: 'offer_slots'; days: 1 | 3 | 7 }
  | { kind: 'send_aftercare_pdf' }
  | { kind: 'request_deposit' }

export interface SmartReply {
  id: string
  label: string
  action: SmartReplyAction
}

// ─── triageConversation ────────────────────────────────────────────────────────

/**
 * Calls the `triage_conversation` RPC (SQL-level deterministic rules).
 * Updates conversations.triage_tag in DB and returns the applied tag.
 * Uses service-role client since this is called from webhook handler.
 */
export async function triageConversation(
  _studioId: string,
  conversationId: string,
): Promise<TriageTag> {
  const supabase = createServiceRoleClient()

  const { data, error } = await supabase.rpc('triage_conversation', {
    p_conversation_id: conversationId,
  })

  if (error || !data) {
    logger.error({ err: error, conversationId }, 'triage: triage_conversation RPC failed')
    return 'client' // safe fallback
  }

  return data as TriageTag
}

// ─── generateSmartReplies ──────────────────────────────────────────────────────

/**
 * v1 rule-based smart reply chips.
 * Returns 2-4 chips derived from triage_tag + message body keywords + upcoming bookings.
 * Each action is fully described so the UI can fire without extra context fetches.
 */
export async function generateSmartReplies(
  ctx: SmartReplyContext,
): Promise<SmartReply[]> {
  const { conversation, lastInboundMessage, upcomingBookings } = ctx
  const triageTag = conversation.triage_tag as TriageTag | null
  const body = lastInboundMessage?.body?.toLowerCase() ?? ''

  const chips: SmartReply[] = []

  // ── Aftercare / healing keywords ──────────────────────────────────────────
  if (/aftercare|healing|heal/.test(body)) {
    chips.push({
      id: 'aftercare-pdf',
      label: 'Send aftercare guide',
      action: { kind: 'send_aftercare_pdf' },
    })
    chips.push({
      id: 'book-followup',
      label: 'Book follow-up',
      action: { kind: 'send_template', templateSlug: 'booking-confirmation' },
    })
    return chips.slice(0, 4)
  }

  // ── Deposit keyword ────────────────────────────────────────────────────────
  if (/deposit/.test(body)) {
    chips.push({
      id: 'request-deposit',
      label: 'Request deposit',
      action: { kind: 'request_deposit' },
    })
    return chips.slice(0, 4)
  }

  // ── Rescheduling triage ────────────────────────────────────────────────────
  if (triageTag === 'rescheduling') {
    const nextBooking = upcomingBookings[0]
    if (nextBooking) {
      chips.push({
        id: 'reschedule-calendar',
        label: 'Reschedule booking',
        action: { kind: 'open_calendar_reschedule', bookingId: nextBooking.id },
      })
    }
    chips.push({
      id: 'offer-slots-1',
      label: 'Check availability — tomorrow',
      action: { kind: 'offer_slots', days: 1 },
    })
    chips.push({
      id: 'offer-slots-3',
      label: 'Offer alternate slots (3 days)',
      action: { kind: 'offer_slots', days: 3 },
    })
    return chips.slice(0, 4)
  }

  // ── Pricing / inquiry triage ───────────────────────────────────────────────
  if (triageTag === 'pricing' || triageTag === 'inquiry') {
    chips.push({
      id: 'inquiry-reply',
      label: 'Send booking form link',
      action: { kind: 'send_template', templateSlug: 'inquiry-reply' },
    })
    chips.push({
      id: 'share-portfolio',
      label: 'Share portfolio',
      action: { kind: 'share_portfolio' },
    })
    return chips.slice(0, 4)
  }

  // ── Deposit paid triage ────────────────────────────────────────────────────
  if (triageTag === 'deposit_paid') {
    chips.push({
      id: 'booking-conf',
      label: 'Send booking confirmation',
      action: { kind: 'send_template', templateSlug: 'booking-confirmation' },
    })
    chips.push({
      id: 'send-aftercare',
      label: 'Send aftercare guide',
      action: { kind: 'send_aftercare_pdf' },
    })
    return chips.slice(0, 4)
  }

  // ── Default: booking context ───────────────────────────────────────────────
  const hasUpcoming = upcomingBookings.length > 0
  if (hasUpcoming) {
    const nextBooking = upcomingBookings[0]
    chips.push({
      id: 'reschedule-default',
      label: 'Reschedule',
      action: { kind: 'open_calendar_reschedule', bookingId: nextBooking.id },
    })
  }
  chips.push({
    id: 'share-portfolio-default',
    label: 'Share portfolio',
    action: { kind: 'share_portfolio' },
  })

  return chips.slice(0, 4)
}

// ─── fireAutoReplyIfMatched ────────────────────────────────────────────────────

/**
 * Checks active auto-reply rules for the studio, matches inbound message,
 * and fires an auto-reply via enqueue_auto_reply RPC + BullMQ if matched.
 *
 * SMS auto-reply is fully functional in v1.
 * TODO(v2-email-worker): email auto-reply skipped — send-email worker not yet
 * integrated with auto-reply comm rows. Add send-email job dispatch here once
 * the worker supports commId-based dispatch.
 */
export async function fireAutoReplyIfMatched(
  studioId: string,
  conversationId: string,
  incomingCommId: string,
): Promise<{ fired: boolean; commId?: string | undefined }> {
  try {
    // Load active rules for this studio
    const rules = await listAutoReplyRules(studioId)
    const activeRules = rules.filter((r) => r.enabled)

    if (activeRules.length === 0) {
      return { fired: false }
    }

    // Load conversation state (triage_tag, last_auto_reply_at, channel)
    const supabase = createServiceRoleClient()

    const { data: conv, error: convErr } = await supabase
      .from('conversations')
      .select('id, triage_tag, last_auto_reply_at, channel, client_id')
      .eq('id', conversationId)
      .eq('studio_id', studioId)
      .single()

    if (convErr || !conv) {
      logger.warn({ conversationId, studioId }, 'auto-reply: conversation not found')
      return { fired: false }
    }

    // Load incoming message body
    const { data: incomingComm, error: commErr } = await supabase
      .from('client_communications')
      .select('body, metadata, direction')
      .eq('id', incomingCommId)
      .single()

    if (commErr || !incomingComm) {
      logger.warn({ incomingCommId }, 'auto-reply: incoming comm not found')
      return { fired: false }
    }

    // Only fire auto-replies on inbound messages
    if (incomingComm.direction !== 'inbound') {
      return { fired: false }
    }

    const messageBody = (incomingComm.body ?? '').toLowerCase()
    const messageMetadata = incomingComm.metadata as Record<string, unknown> | null
    const triageTag = conv.triage_tag as TriageTag | null

    // Find first matching rule (ordered by created_at asc — already sorted by listAutoReplyRules)
    let matchedRuleId: string | null = null

    for (const rule of activeRules) {
      let matched = false

      if (rule.trigger_type === 'new_inquiry' && triageTag === 'inquiry') {
        matched = true
      } else if (
        rule.trigger_type === 'keyword' &&
        rule.keyword &&
        messageBody.includes(rule.keyword.toLowerCase())
      ) {
        matched = true
      } else if (
        rule.trigger_type === 'missed_call' &&
        triageTag === 'missed_call'
      ) {
        matched = true
      } else if (
        rule.trigger_type === 'deposit_paid' &&
        messageMetadata?.['kind'] === 'deposit_paid'
      ) {
        matched = true
      }

      if (matched) {
        matchedRuleId = rule.id
        break
      }
    }

    if (!matchedRuleId) {
      return { fired: false }
    }

    // Call RPC enqueue_auto_reply — handles cooldown check + comm insert
    const { data: newCommId, error: rpcErr } = await supabase.rpc('enqueue_auto_reply', {
      p_conversation_id: conversationId,
      p_rule_id: matchedRuleId,
    })

    if (rpcErr) {
      logger.error({ err: rpcErr, conversationId, matchedRuleId }, 'auto-reply: enqueue_auto_reply RPC failed')
      return { fired: false }
    }

    // RPC returns null when cooldown has not elapsed
    if (!newCommId) {
      logger.info({ conversationId, matchedRuleId }, 'auto-reply: cooldown not elapsed — skipped')
      return { fired: false }
    }

    const commId = newCommId as string

    // Enqueue BullMQ send-sms job (SMS is the dominant v1 channel)
    // Email auto-reply: skipped — see TODO above
    if (conv.channel === 'sms') {
      await enqueueJob('send-sms', { commId, studioId })
      logger.info({ conversationId, commId, matchedRuleId }, 'auto-reply: SMS job enqueued')
    } else {
      logger.info(
        { conversationId, channel: conv.channel },
        'auto-reply: email auto-reply skipped — no email worker for auto-reply path in v1',
      )
    }

    return { fired: true, commId }
  } catch (err) {
    logger.error({ err, conversationId, studioId }, 'auto-reply: unexpected error in fireAutoReplyIfMatched')
    return { fired: false }
  }
}

