// ─── Types ────────────────────────────────────────────────────────────────────

export interface ActionResult<T = undefined> {
  ok: boolean
  data?: T | undefined
  error?: string | undefined
}

// ─── Revalidate helper ────────────────────────────────────────────────────────

function revalidateMessages() {
  revalidatePath('/messages')
  revalidatePath('/settings/messaging')
}

// ─── sendMessageAction ────────────────────────────────────────────────────────

const SendMessageSchema = z.object({
  conversationId: z.string().uuid(),
  clientId: z.string().uuid(),
  body: z.string().min(1).max(1600),
  channel: z.enum(['sms', 'email']),
  subject: z.string().max(200).optional(),
})

export async function sendMessageAction(
  input: z.infer<typeof SendMessageSchema>,
): Promise<ActionResult<{ commId: string }>> {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return { ok: false, error: 'Unauthorized' }

  const parsed = SendMessageSchema.safeParse(input)
  if (!parsed.success) {
    return { ok: false, error: parsed.error.issues[0]?.message ?? 'Invalid input' }
  }

  const { conversationId, clientId, body, channel, subject } = parsed.data
  const { studioId } = authUser

  try {
    if (channel === 'sms') {
      const result = await sendSmsToClient(
        { studioId, clientId, body },
        authUser.user.id,
      )
      if (!result.ok) {
        return { ok: false, error: result.error ?? 'Failed to send SMS' }
      }
      revalidateMessages()
      return { ok: true, data: { commId: result.commId ?? '' } }
    }

    if (channel === 'email') {
      const result = await sendEmailToClient(
        {
          studioId,
          clientId,
          subject: subject ?? '(no subject)',
          body,
        },
        authUser.user.id,
      )
      if (!result.ok) {
        return { ok: false, error: result.error ?? 'Failed to send email' }
      }
      revalidateMessages()
      return { ok: true, data: { commId: result.commId ?? '' } }
    }

    return { ok: false, error: 'Unsupported channel' }
  } catch (err) {
    logger.error({ err, conversationId }, 'sendMessageAction: unexpected error')
    return { ok: false, error: 'Failed to send message' }
  }
}

