export type { SmartReplyAction }

import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { getActiveStudio, NoStudioMembershipError } from '@/lib/context/active-studio'
import { getAuthenticatedUser } from '@/lib/supabase/server'
import {
  listConversations,
  getConversation,
  getConversationMessages,
  getConversationContext,
  getChannelUnreadCounts,
  listMessageTemplates,
} from '@/lib/messaging/queries'
import { markConversationRead } from '@/lib/messaging/mutations'
import { MessagesShell } from '@/components/messages/MessagesShell'
import { PageShell } from '@/components/shared/PageShell'
import { PageHeader } from '@/components/shared/PageHeader'
import type { ConversationContext } from '@/lib/messaging/queries'

export const metadata: Metadata = {
  title: 'Messages — InkOS',
}

// Next 16 — searchParams must be awaited
interface SearchParams {
  c?: string
  channel?: string
  filter?: string
  q?: string
}

export default async function MessagesPage({
  searchParams,
}: {
  searchParams: Promise<SearchParams>
}) {
  let studioId: string

  try {
    const ctx = await getActiveStudio()
    studioId = ctx.studioId
  } catch (err) {
    if (err instanceof NoStudioMembershipError) redirect('/onboarding')
    redirect('/onboarding')
  }

  const params = await searchParams
  const activeConversationId = params.c ?? null
  const channelFilter = params.channel ?? null
  const filterParam = params.filter ?? null
  const searchQuery = params.q ?? null

  // Resolve 'me' assignedTo filter — get current user id
  let resolvedAssignedTo: string | undefined
  if (filterParam === 'assigned-to-me') {
    const authUser = await getAuthenticatedUser()
    resolvedAssignedTo = authUser?.user.id
  }

  // Parallel fetch: conversation list + channel unread counts + templates
  const [listResult, unreadCounts, templates] = await Promise.all([
    listConversations(studioId, {
      limit: 50,
      archived: filterParam === 'archived',
      unreadOnly: filterParam === 'unread',
      starred: filterParam === 'starred' ? true : undefined,
      resolved: filterParam === 'resolved' ? true : undefined,
      channel: channelFilter as Parameters<typeof listConversations>[1]['channel'] ?? undefined,
      search: searchQuery ?? undefined,
      assignedTo: resolvedAssignedTo,
    }),
    getChannelUnreadCounts(studioId),
    listMessageTemplates(studioId),
  ])

  const { conversations } = listResult

  // Fetch active conversation data if c= param is set
  let activeConversation = null
  let activeMessages: Awaited<ReturnType<typeof getConversationMessages>> = []
  let conversationContext: ConversationContext | null = null

  if (activeConversationId) {
    // Parallel fetch: conversation + messages + context pane data
    const [conv, msgs, ctx] = await Promise.all([
      getConversation(studioId, activeConversationId),
      getConversationMessages(studioId, activeConversationId, { limit: 50 }),
      getConversationContext(studioId, activeConversationId),
    ])

    activeConversation = conv
    activeMessages = msgs
    conversationContext = ctx

