/**
 * Instagram / Meta Graph webhook handler.
 *
 * GET  — Meta subscription verification challenge.
 * POST — Inbound IG DM stub. Verifies X-Hub-Signature-256 HMAC-SHA256.
 *        Logs body + returns 200. No message ingest in v1.
 *
 * Activate when Meta App Review + PAGE_ACCESS_TOKEN lands.
 * Feature gate: omnichannel_inbox (Studio+). Studio routing is v2 work
 * (requires mapping IG page_id → studio). v1 returns 200 immediately after
 * signature verification. TODO(v2): route by page_id + ingest comm row.
 */

import { type NextRequest, NextResponse } from 'next/server'
import { createHmac, timingSafeEqual } from 'crypto'
import { apiRatelimit } from '@/lib/rate-limit.ts'
import { logger } from '@/lib/logger'

// ─── GET — Meta subscription verification ─────────────────────────────────────

export async function GET(request: NextRequest): Promise<NextResponse> {
  const { searchParams } = new URL(request.url)
  const mode = searchParams.get('hub.mode')
  const token = searchParams.get('hub.verify_token')
  const challenge = searchParams.get('hub.challenge')

  if (mode === 'subscribe' && token === process.env.META_WEBHOOK_VERIFY_TOKEN) {
    logger.info({}, 'instagram-webhook: subscription verified')
    return new NextResponse(challenge ?? '', {
      status: 200,
      headers: { 'Content-Type': 'text/plain' },
    })
  }

  logger.warn({ mode, tokenMatch: token === process.env.META_WEBHOOK_VERIFY_TOKEN }, 'instagram-webhook: verification failed')
  return new NextResponse('Forbidden', { status: 403 })
}

// ─── POST — Inbound IG DM ─────────────────────────────────────────────────────

export async function POST(request: NextRequest): Promise<NextResponse> {
  // Rate-limit: apply to POST only (GET is low-volume challenge ping)
  const ip = request.headers.get('x-forwarded-for') ?? 'unknown'
  const rl = await apiRatelimit.limit(ip)
  if (!rl.success) {
    return new NextResponse('Too many requests', { status: 429 })
  }

  // Read raw body for HMAC verification
  let rawBody: string
  try {
    rawBody = await request.text()
  } catch {
    return new NextResponse('Bad request', { status: 400 })
  }

  // Verify X-Hub-Signature-256
  const appSecret = process.env.META_APP_SECRET
  if (!appSecret) {
    logger.error({}, 'instagram-webhook: META_APP_SECRET not set — rejecting')
    return new NextResponse('Webhook not configured', { status: 200 })
  }

  const signature = request.headers.get('x-hub-signature-256') ?? ''
  const signatureBuffer = Buffer.from(signature.replace('sha256=', ''), 'hex')
  const expectedBuffer = createHmac('sha256', appSecret)
    .update(rawBody)
    .digest()

  const valid =
    signatureBuffer.length === expectedBuffer.length &&
    timingSafeEqual(signatureBuffer, expectedBuffer)

  if (!valid) {
    logger.warn({}, 'instagram-webhook: invalid X-Hub-Signature-256 — rejecting')
    return new NextResponse('Forbidden', { status: 403 })
  }

  // TODO(v2): parse payload, route by page_id → studio_id, ingest comm row,
  // call triageConversation + fireAutoReplyIfMatched.
  // Requires feature gate omnichannel_inbox check after studio routing resolves.
  logger.info({ bodyLength: rawBody.length }, 'instagram-webhook: received (stub — ingest v2)')

  return new NextResponse(null, { status: 200 })
}

/**
 * WhatsApp / Meta Cloud API webhook handler.
 *
 * GET  — Meta subscription verification challenge (same flow as IG).
 * POST — Inbound WA message stub. Verifies X-Hub-Signature-256 HMAC-SHA256
 *        against META_WHATSAPP_APP_SECRET (separate from IG secret so each
 *        Meta app can have independent credentials).
 *
 * No message ingest in v1. TODO(v2): route by phone_number_id → studio_id,
 * ingest comm row, call triage + auto-reply.
 *
 * Feature gate: omnichannel_inbox (Studio+). Studio routing is v2 work.
 */

import { type NextRequest, NextResponse } from 'next/server'
import { createHmac, timingSafeEqual } from 'crypto'
import { apiRatelimit } from '@/lib/rate-limit.ts'
import { logger } from '@/lib/logger'

// ─── GET — Meta subscription verification ─────────────────────────────────────

export async function GET(request: NextRequest): Promise<NextResponse> {
  const { searchParams } = new URL(request.url)
  const mode = searchParams.get('hub.mode')
  const token = searchParams.get('hub.verify_token')
  const challenge = searchParams.get('hub.challenge')

  // WhatsApp may use a separate verify token from IG
  const verifyToken =
    process.env.META_WHATSAPP_WEBHOOK_VERIFY_TOKEN ??
    process.env.META_WEBHOOK_VERIFY_TOKEN

  if (mode === 'subscribe' && token === verifyToken) {
    logger.info({}, 'whatsapp-webhook: subscription verified')
    return new NextResponse(challenge ?? '', {
      status: 200,
      headers: { 'Content-Type': 'text/plain' },
    })
  }

  logger.warn({ mode }, 'whatsapp-webhook: verification failed')
  return new NextResponse('Forbidden', { status: 403 })
}

// ─── POST — Inbound WA message ────────────────────────────────────────────────

export async function POST(request: NextRequest): Promise<NextResponse> {
  const ip = request.headers.get('x-forwarded-for') ?? 'unknown'
  const rl = await apiRatelimit.limit(ip)
  if (!rl.success) {
    return new NextResponse('Too many requests', { status: 429 })
  }

  let rawBody: string
  try {
    rawBody = await request.text()
  } catch {
    return new NextResponse('Bad request', { status: 400 })
  }

  // Verify X-Hub-Signature-256 using the WhatsApp app secret
  const appSecret =
    process.env.META_WHATSAPP_APP_SECRET ?? process.env.META_APP_SECRET

  if (!appSecret) {
    logger.error({}, 'whatsapp-webhook: app secret not set — rejecting')
    return new NextResponse('Webhook not configured', { status: 200 })
  }

  const signature = request.headers.get('x-hub-signature-256') ?? ''
  const signatureBuffer = Buffer.from(signature.replace('sha256=', ''), 'hex')
  const expectedBuffer = createHmac('sha256', appSecret)
    .update(rawBody)
    .digest()

  const valid =
    signatureBuffer.length === expectedBuffer.length &&
    timingSafeEqual(signatureBuffer, expectedBuffer)

  if (!valid) {
    logger.warn({}, 'whatsapp-webhook: invalid X-Hub-Signature-256 — rejecting')
    return new NextResponse('Forbidden', { status: 403 })
  }

  // TODO(v2): parse payload, route by phone_number_id → studio_id, ingest comm row.
  logger.info({ bodyLength: rawBody.length }, 'whatsapp-webhook: received (stub — ingest v2)')

  return new NextResponse(null, { status: 200 })
}

/**
 * Web chat widget webhook handler.
 *
 * POST only. Verifies shared-secret HMAC-SHA256 in X-Webchat-Signature header
 * against WEBCHAT_WEBHOOK_SECRET env var.
 *
 * No message ingest in v1. TODO(v2): parse payload, route by widget_token →
 * studio_id, ingest comm row, call triage + auto-reply.
 *
 * Feature gate: omnichannel_inbox (Studio+). Studio routing is v2 work.
 */

import { type NextRequest, NextResponse } from 'next/server'
import { createHmac, timingSafeEqual } from 'crypto'
import { apiRatelimit } from '@/lib/rate-limit.ts'
import { logger } from '@/lib/logger'

// ─── POST — Inbound web chat message ─────────────────────────────────────────

export async function POST(request: NextRequest): Promise<NextResponse> {
  const ip = request.headers.get('x-forwarded-for') ?? 'unknown'
  const rl = await apiRatelimit.limit(ip)
  if (!rl.success) {
    return new NextResponse('Too many requests', { status: 429 })
  }

  let rawBody: string
  try {
    rawBody = await request.text()
  } catch {
    return new NextResponse('Bad request', { status: 400 })
  }

  // Verify X-Webchat-Signature (HMAC-SHA256 of raw body)
  const secret = process.env.WEBCHAT_WEBHOOK_SECRET
  if (!secret) {
    logger.error({}, 'webchat-webhook: WEBCHAT_WEBHOOK_SECRET not set — rejecting')
    return new NextResponse('Webhook not configured', { status: 200 })
  }

  const signature = request.headers.get('x-webchat-signature') ?? ''
  const signatureBuffer = Buffer.from(signature.replace('sha256=', ''), 'hex')
  const expectedBuffer = createHmac('sha256', secret)
    .update(rawBody)
    .digest()

  const valid =
    signatureBuffer.length === expectedBuffer.length &&
    timingSafeEqual(signatureBuffer, expectedBuffer)

  if (!valid) {
    logger.warn({}, 'webchat-webhook: invalid X-Webchat-Signature — rejecting')
    return new NextResponse('Forbidden', { status: 403 })
  }

  // TODO(v2): parse payload, route by widget_token → studio_id, ingest comm row.
  logger.info({ bodyLength: rawBody.length }, 'webchat-webhook: received (stub — ingest v2)')

  return new NextResponse(null, { status: 200 })
}

/**
 * send-scheduled-message BullMQ worker.
 *
 * Consumes 'send-scheduled-message' jobs from the inkos-jobs queue.
 * Job payload: { commId: string; studioId: string }
 *   commId   — client_communications.id with status='queued' + scheduled_for set
 *   studioId — logging context + studio phone number lookup
 *
 * Dispatches via:
 *   - channel='sms'   → Twilio
 *   - channel='email' → Resend
 *
 * Retry strategy: 3 attempts, exponential backoff (1s, 5s, 25s).
 * Idempotent: skips rows already in a terminal state (sent/delivered/failed).
 */

import { Worker } from 'bullmq'
import { Twilio } from 'twilio'
import { Resend } from 'resend'
import { supabase } from '../lib/supabase'
import { logger } from '../lib/logger'
import { workerEnv } from '../lib/env'

const QUEUE_NAME = 'inkos-jobs'
const JOB_NAME = 'send-scheduled-message'

// ─── Payload type ─────────────────────────────────────────────────────────────

interface SendScheduledMessagePayload {
  commId: string
  studioId: string
}

function isValidPayload(data: unknown): data is SendScheduledMessagePayload {
  return (
    typeof data === 'object' &&
    data !== null &&
    typeof (data as Record<string, unknown>)['commId'] === 'string' &&
    typeof (data as Record<string, unknown>)['studioId'] === 'string'
  )
}

// ─── Twilio client (lazy) ─────────────────────────────────────────────────────

let _twilio: Twilio | null = null

function getTwilioClient(): Twilio | null {
  if (!workerEnv.TWILIO_ACCOUNT_SID || !workerEnv.TWILIO_AUTH_TOKEN) return null
  if (!_twilio) {
    _twilio = new Twilio(workerEnv.TWILIO_ACCOUNT_SID, workerEnv.TWILIO_AUTH_TOKEN)
  }
  return _twilio
}

// ─── Resend client (lazy) ─────────────────────────────────────────────────────

let _resend: Resend | null = null

function getResendClient(): Resend | null {
  if (!workerEnv.RESEND_API_KEY) return null
  if (!_resend) {
    _resend = new Resend(workerEnv.RESEND_API_KEY)
  }
  return _resend
}

// ─── Worker ───────────────────────────────────────────────────────────────────

export function createSendScheduledMessageWorker() {
  const worker = new Worker(
    QUEUE_NAME,
    async (job) => {
      if (job.name !== JOB_NAME) return

      if (!isValidPayload(job.data)) {
        logger.error({ jobId: job.id, data: job.data }, 'send-scheduled-message: invalid payload — skipping')
        return
      }

      const { commId, studioId } = job.data
      const workerLog = logger.child({ jobId: job.id, commId, studioId })
      workerLog.info('send-scheduled-message: processing')

      // ── 1. Fetch comm row ─────────────────────────────────────────────────
      const { data: comm, error: commErr } = await supabase
        .from('client_communications')
        .select('id, status, body, subject, client_id, studio_id, channel, scheduled_for, is_internal_note')
        .eq('id', commId)
        .single()

      if (commErr || !comm) {
        workerLog.error({ err: commErr }, 'send-scheduled-message: comm row not found')
        throw new Error(`comm row not found: ${commId}`)
      }

      // Internal notes are never dispatched
      if (comm.is_internal_note) {
        workerLog.info('send-scheduled-message: comm is internal note — skipping dispatch')
        return
      }

      // ── 2. Idempotency guard ──────────────────────────────────────────────
      const terminalStatuses = ['sent', 'delivered', 'failed', 'bounced'] as const
      if (terminalStatuses.includes(comm.status as typeof terminalStatuses[number])) {
        workerLog.info({ status: comm.status }, 'send-scheduled-message: already terminal — skipping')
        return
      }

      // ── 3. Defensive: check scheduled_for <= now() ────────────────────────
      if (comm.scheduled_for) {
        const scheduledAt = new Date(comm.scheduled_for).getTime()
        if (scheduledAt > Date.now() + 5_000) {
          // More than 5s in the future — re-queue with remaining delay
          const remainingMs = scheduledAt - Date.now()
          workerLog.warn({ scheduledFor: comm.scheduled_for, remainingMs }, 'send-scheduled-message: too early — re-queuing')
          throw new Error(`Scheduled time not reached yet (${remainingMs}ms remaining)`)
        }
      }

      // ── 4. Dispatch by channel ────────────────────────────────────────────
      if (comm.channel === 'sms') {
        await dispatchSms(comm, studioId, workerLog)
      } else if (comm.channel === 'email') {
        await dispatchEmail(comm, studioId, workerLog)
      } else {
        workerLog.warn({ channel: comm.channel }, 'send-scheduled-message: unsupported channel — skipping')
        await supabase
          .from('client_communications')
          .update({ status: 'failed', error: `Unsupported channel: ${comm.channel}`, updated_at: new Date().toISOString() })
          .eq('id', commId)
      }
    },
    {
      connection: {
        url: workerEnv.REDIS_URL,
        maxRetriesPerRequest: null,
      },
      concurrency: 5,
      // 3 attempts: 1s → 5s → 25s (exponential, base 1000ms)
    },
  )

  worker.on('completed', (job) => {
    logger.info({ jobId: job.id }, 'send-scheduled-message: completed')
  })

  worker.on('failed', (job, err) => {
    logger.error({ jobId: job?.id, err }, 'send-scheduled-message: failed')
  })

  worker.on('error', (err) => {
    logger.error({ err }, 'send-scheduled-message: worker error')
  })

  return worker
}

// ─── dispatchSms ──────────────────────────────────────────────────────────────

async function dispatchSms(
  comm: { id: string; body: string; client_id: string; studio_id: string },
  studioId: string,
  workerLog: ReturnType<typeof logger.child>,
): Promise<void> {
  const twilioClient = getTwilioClient()
  if (!twilioClient) {
    workerLog.warn('send-scheduled-message: Twilio not configured — marking failed')
    await supabase
      .from('client_communications')
      .update({ status: 'failed', error: 'Twilio not configured', updated_at: new Date().toISOString() })
      .eq('id', comm.id)
    return
  }

  // Resolve client phone
  const { data: client, error: clientErr } = await supabase
    .from('clients')
    .select('phone')
    .eq('id', comm.client_id)
    .single()

  if (clientErr || !client?.phone) {
    workerLog.warn('send-scheduled-message: client has no phone — marking failed')
    await supabase
      .from('client_communications')
      .update({ status: 'failed', error: 'Client has no phone number', updated_at: new Date().toISOString() })
      .eq('id', comm.id)
    return
  }

  // Resolve studio From number
  const { data: studio } = await supabase
    .from('studios')
    .select('twilio_phone_number')
    .eq('id', studioId)
    .single()

  const fromNumber = studio?.twilio_phone_number ?? workerEnv.TWILIO_PHONE_NUMBER

  if (!fromNumber) {
    workerLog.error('send-scheduled-message: no From number available')
    await supabase
      .from('client_communications')
      .update({ status: 'failed', error: 'No Twilio From number configured', updated_at: new Date().toISOString() })
      .eq('id', comm.id)
    return
  }

  try {
    const message = await twilioClient.messages.create({
      from: fromNumber,
      to: client.phone,
      body: comm.body,
    })

    await supabase
      .from('client_communications')
      .update({
        status: 'sent',
        provider_message_id: message.sid,
        sent_at: new Date().toISOString(),
        error: null,
        updated_at: new Date().toISOString(),
      })
      .eq('id', comm.id)

    workerLog.info({ sid: message.sid }, 'send-scheduled-message: SMS sent')
  } catch (err: unknown) {
    const errMsg = err instanceof Error ? err.message : String(err)
    workerLog.error({ err }, 'send-scheduled-message: Twilio send failed')
    await supabase
      .from('client_communications')
      .update({ status: 'failed', error: errMsg, updated_at: new Date().toISOString() })
      .eq('id', comm.id)
    throw err
  }
}

// ─── dispatchEmail ────────────────────────────────────────────────────────────

async function dispatchEmail(
  comm: { id: string; body: string; subject: string | null; client_id: string; studio_id: string },
  _studioId: string,
  workerLog: ReturnType<typeof logger.child>,
): Promise<void> {
  const resend = getResendClient()
  if (!resend) {
    workerLog.warn('send-scheduled-message: Resend not configured — marking failed')
    await supabase
      .from('client_communications')
      .update({ status: 'failed', error: 'Resend not configured', updated_at: new Date().toISOString() })
      .eq('id', comm.id)
    return
  }

  // Resolve client email
  const { data: client, error: clientErr } = await supabase
    .from('clients')
    .select('email, first_name, last_name')
    .eq('id', comm.client_id)
    .single()

  if (clientErr || !client?.email) {
    workerLog.warn('send-scheduled-message: client has no email — marking failed')
    await supabase
      .from('client_communications')
      .update({ status: 'failed', error: 'Client has no email address', updated_at: new Date().toISOString() })
      .eq('id', comm.id)
    return
  }

  try {
    const { error: sendErr } = await resend.emails.send({
      from: workerEnv.RESEND_FROM_EMAIL,
      to: client.email,
      replyTo: workerEnv.RESEND_REPLY_TO,
      subject: comm.subject ?? '(no subject)',
      text: comm.body,
    })

    if (sendErr) {
      throw new Error(sendErr.message)
    }

    await supabase
      .from('client_communications')
      .update({
        status: 'sent',
        sent_at: new Date().toISOString(),
        error: null,
        updated_at: new Date().toISOString(),
      })
      .eq('id', comm.id)

    workerLog.info({ to: client.email }, 'send-scheduled-message: email sent')
  } catch (err: unknown) {
    const errMsg = err instanceof Error ? err.message : String(err)
    workerLog.error({ err }, 'send-scheduled-message: Resend send failed')
    await supabase
      .from('client_communications')
      .update({ status: 'failed', error: errMsg, updated_at: new Date().toISOString() })
      .eq('id', comm.id)
    throw err
  }
}

